CREATE TABLE bucket_lifecycle_configs (bucket TEXT PRIMARY KEY NOT NULL REFERENCES buckets(name) ON DELETE CASCADE, canonical_json @LIFECYCLE_JSON@, revision BIGINT NOT NULL, scan_cursor TEXT, scan_lease_epoch BIGINT NOT NULL DEFAULT 0, scan_lease_until @TIME@, created_at @TIME@ NOT NULL, updated_at @TIME@ NOT NULL, last_scanned_at @TIME@, @JSON_CHECK@ CONSTRAINT ck_bucket_lifecycle_configs_revision CHECK(revision>0), CONSTRAINT ck_bucket_lifecycle_configs_scan_lease_epoch CHECK(scan_lease_epoch>=0));
CREATE TABLE physical_residencies (tier TEXT NOT NULL, cid TEXT NOT NULL, node_identity TEXT, verification_state TEXT NOT NULL, verification_receipt TEXT, verified_at @TIME@, created_at @TIME@ NOT NULL, updated_at @TIME@ NOT NULL, PRIMARY KEY(tier,cid), CONSTRAINT ck_physical_residencies_tier CHECK(tier IN ('hot','cold')), CONSTRAINT ck_physical_residencies_cid CHECK(length(cid)>0), CONSTRAINT ck_physical_residencies_verification_state CHECK(verification_state IN ('pending','verified','failed')), CONSTRAINT ck_physical_residencies_verification_shape CHECK((verification_state='verified' AND node_identity IS NOT NULL AND length(node_identity)>0 AND verification_receipt IS NOT NULL AND length(verification_receipt)>0 AND verified_at IS NOT NULL) OR (verification_state IN ('pending','failed') AND node_identity IS NULL AND verification_receipt IS NULL AND verified_at IS NULL)));
CREATE TABLE version_residencies (version_row_id TEXT PRIMARY KEY NOT NULL, object_id TEXT NOT NULL, primary_tier TEXT NOT NULL, storage_class TEXT NOT NULL, cid TEXT NOT NULL, revision BIGINT NOT NULL, created_at @TIME@ NOT NULL, updated_at @TIME@ NOT NULL, CONSTRAINT fk_version_residencies_owner FOREIGN KEY(version_row_id,object_id) REFERENCES object_versions(id,object_id) ON DELETE CASCADE, CONSTRAINT fk_version_residencies_object_content FOREIGN KEY(object_id,cid) REFERENCES objects(id,cid) ON DELETE CASCADE, CONSTRAINT fk_version_residencies_physical FOREIGN KEY(primary_tier,cid) REFERENCES physical_residencies(tier,cid), CONSTRAINT ck_version_residencies_revision CHECK(revision>0), CONSTRAINT ck_version_residencies_primary CHECK((primary_tier='hot' AND storage_class='STANDARD') OR (primary_tier='cold' AND storage_class='STANDARD_IA')));
CREATE TABLE residency_references (owner_kind TEXT NOT NULL, owner_id TEXT NOT NULL, reason TEXT NOT NULL, version_row_id TEXT NOT NULL, object_id TEXT NOT NULL, tier TEXT NOT NULL, cid TEXT NOT NULL, created_at @TIME@ NOT NULL, PRIMARY KEY(owner_kind,owner_id,reason,tier,cid), CONSTRAINT fk_residency_references_version FOREIGN KEY(version_row_id,object_id) REFERENCES object_versions(id,object_id) ON DELETE CASCADE, CONSTRAINT fk_residency_references_object_content FOREIGN KEY(object_id,cid) REFERENCES objects(id,cid) ON DELETE CASCADE, CONSTRAINT fk_residency_references_physical FOREIGN KEY(tier,cid) REFERENCES physical_residencies(tier,cid), CONSTRAINT ck_residency_references_owner_kind CHECK(owner_kind IN ('version','transition')), CONSTRAINT ck_residency_references_reason CHECK(reason IN ('retained_version','transition_staging','transition_cleanup_hold')), CONSTRAINT ck_residency_references_owner_shape CHECK((owner_kind='version' AND reason='retained_version' AND owner_id=version_row_id) OR (owner_kind='transition' AND reason IN ('transition_staging','transition_cleanup_hold') AND length(owner_id)>0)));
CREATE TABLE residency_backfill (id TEXT PRIMARY KEY NOT NULL, cursor_version_row_id TEXT, claim_epoch BIGINT NOT NULL DEFAULT 0, lease_until @TIME@, claimed_by TEXT, completed BOOLEAN NOT NULL DEFAULT FALSE, updated_at @TIME@ NOT NULL, CONSTRAINT ck_residency_backfill_singleton CHECK(id='hot_verification'), CONSTRAINT ck_residency_backfill_cursor CHECK(cursor_version_row_id IS NULL OR length(cursor_version_row_id)>0), CONSTRAINT ck_residency_backfill_epoch CHECK(claim_epoch>=0), CONSTRAINT ck_residency_backfill_claim CHECK((lease_until IS NULL AND claimed_by IS NULL) OR (lease_until IS NOT NULL AND claimed_by IS NOT NULL AND length(claimed_by)>0)));
CREATE INDEX idx_version_residencies_object ON version_residencies(object_id,version_row_id);
CREATE INDEX idx_version_residencies_physical ON version_residencies(primary_tier,cid,version_row_id);
CREATE INDEX idx_physical_residencies_verification ON physical_residencies(tier,verification_state,cid);
CREATE INDEX idx_residency_references_physical ON residency_references(tier,cid,reason,owner_id);
CREATE INDEX idx_residency_references_version ON residency_references(version_row_id,reason,owner_id);
CREATE TABLE lifecycle_actions (id TEXT PRIMARY KEY NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, bucket TEXT NOT NULL REFERENCES buckets(name) ON DELETE CASCADE, object_key TEXT NOT NULL, config_revision BIGINT NOT NULL, rule_id TEXT NOT NULL, action_kind TEXT NOT NULL, target_type TEXT NOT NULL, target_version_row_id TEXT, target_public_version_id TEXT, target_object_id TEXT, target_sequence BIGINT, target_upload_id TEXT, target_upload_created_at @TIME@, due_at @TIME@ NOT NULL, state TEXT NOT NULL, attempts BIGINT NOT NULL DEFAULT 0, next_attempt_at @TIME@ NOT NULL, claim_epoch BIGINT NOT NULL DEFAULT 0, lease_until @TIME@, claimed_by TEXT, failure_class TEXT, last_error_redacted TEXT, created_at @TIME@ NOT NULL, updated_at @TIME@ NOT NULL, finished_at @TIME@, CONSTRAINT ck_lifecycle_actions_config_revision CHECK(config_revision>0), CONSTRAINT ck_lifecycle_actions_action_kind CHECK(action_kind IN ('expire_current','expire_noncurrent','delete_expired_marker','abort_incomplete_multipart_upload','transition_current','transition_noncurrent')), CONSTRAINT ck_lifecycle_actions_target_sequence CHECK(target_sequence IS NULL OR target_sequence>=0), CONSTRAINT ck_lifecycle_actions_target_shape CHECK((target_type='version' AND target_version_row_id IS NOT NULL AND target_public_version_id IS NOT NULL AND target_sequence IS NOT NULL AND target_upload_id IS NULL AND target_upload_created_at IS NULL) OR (target_type='multipart_upload' AND target_version_row_id IS NULL AND target_public_version_id IS NULL AND target_object_id IS NULL AND target_sequence IS NULL AND target_upload_id IS NOT NULL AND target_upload_created_at IS NOT NULL)), CONSTRAINT ck_lifecycle_actions_kind_target CHECK((action_kind IN ('expire_current','expire_noncurrent','delete_expired_marker') AND target_type='version') OR (action_kind='abort_incomplete_multipart_upload' AND target_type='multipart_upload') OR (action_kind IN ('transition_current','transition_noncurrent') AND target_type='version' AND length(target_version_row_id)>0 AND length(target_public_version_id)>0 AND target_object_id IS NOT NULL AND length(target_object_id)>0)), CONSTRAINT ck_lifecycle_actions_state CHECK(state IN ('pending','claimed','succeeded','cancelled','failed_safe')), CONSTRAINT ck_lifecycle_actions_attempts CHECK(attempts>=0), CONSTRAINT ck_lifecycle_actions_claim_epoch CHECK(claim_epoch>=0), CONSTRAINT ck_lifecycle_action_claim CHECK((state='claimed' AND lease_until IS NOT NULL AND claimed_by IS NOT NULL) OR (state<>'claimed' AND lease_until IS NULL AND claimed_by IS NULL)), CONSTRAINT ck_lifecycle_action_terminal CHECK((state IN ('succeeded','cancelled','failed_safe') AND finished_at IS NOT NULL) OR (state IN ('pending','claimed') AND finished_at IS NULL)));
CREATE INDEX idx_lifecycle_actions_due ON lifecycle_actions(state,next_attempt_at,due_at,id);
CREATE INDEX idx_lifecycle_actions_reclaim ON lifecycle_actions(state,lease_until,id);
CREATE INDEX idx_lifecycle_actions_bucket_revision ON lifecycle_actions(bucket,config_revision,id);
CREATE INDEX idx_lifecycle_actions_target ON lifecycle_actions(bucket,object_key,target_version_row_id);
CREATE INDEX idx_lifecycle_actions_multipart_target ON lifecycle_actions(bucket,object_key,target_upload_id,target_upload_created_at);
CREATE TABLE lifecycle_transitions (id TEXT PRIMARY KEY NOT NULL, action_id TEXT NOT NULL UNIQUE REFERENCES lifecycle_actions(id), action_kind TEXT NOT NULL, bucket TEXT NOT NULL REFERENCES buckets(name), object_key TEXT NOT NULL, config_revision BIGINT NOT NULL, rule_id TEXT NOT NULL, target_version_row_id TEXT NOT NULL, target_public_version_id TEXT NOT NULL, target_object_id TEXT NOT NULL, target_sequence BIGINT NOT NULL, source_tier TEXT NOT NULL, destination_tier TEXT NOT NULL, source_cid TEXT NOT NULL, destination_cid TEXT NOT NULL, source_residency_revision BIGINT NOT NULL, expected_source_node_identity TEXT NOT NULL, expected_destination_node_identity TEXT NOT NULL, ownership_generation BIGINT NOT NULL, checkpoint TEXT NOT NULL, verification_receipt TEXT, publication_receipt TEXT, settlement_kind TEXT, created_at @TIME@ NOT NULL, updated_at @TIME@ NOT NULL, completed_at @TIME@, CONSTRAINT fk_lifecycle_transitions_source_physical FOREIGN KEY(source_tier,source_cid) REFERENCES physical_residencies(tier,cid), CONSTRAINT ck_lifecycle_transitions_kind CHECK(action_kind IN ('transition_current','transition_noncurrent')), CONSTRAINT ck_lifecycle_transitions_target CHECK(config_revision>0 AND target_sequence>=0 AND length(target_version_row_id)>0 AND length(target_public_version_id)>0 AND length(target_object_id)>0), CONSTRAINT ck_lifecycle_transitions_direction CHECK(source_tier='hot' AND destination_tier='cold' AND source_cid=destination_cid AND length(source_cid)>0), CONSTRAINT ck_lifecycle_transitions_residency_revision CHECK(source_residency_revision>0), CONSTRAINT ck_lifecycle_transitions_node_identities CHECK(length(expected_source_node_identity)>0 AND length(expected_destination_node_identity)>0 AND expected_source_node_identity<>expected_destination_node_identity), CONSTRAINT ck_lifecycle_transitions_ownership_generation CHECK(ownership_generation>0), CONSTRAINT ck_lifecycle_transitions_checkpoint CHECK(checkpoint IN ('prepare','copy','verify','publish','cleanup')), CONSTRAINT ck_lifecycle_transitions_receipts CHECK((checkpoint IN ('prepare','copy') AND verification_receipt IS NULL AND publication_receipt IS NULL) OR (checkpoint='verify' AND verification_receipt IS NOT NULL AND length(verification_receipt)>0 AND publication_receipt IS NULL) OR (checkpoint IN ('publish','cleanup') AND verification_receipt IS NOT NULL AND length(verification_receipt)>0 AND publication_receipt IS NOT NULL AND length(publication_receipt)>0)), CONSTRAINT ck_lifecycle_transitions_settlement CHECK((settlement_kind IS NULL AND completed_at IS NULL AND checkpoint<>'cleanup') OR (settlement_kind IS NOT NULL AND settlement_kind='cancelled' AND completed_at IS NOT NULL AND checkpoint IN ('prepare','copy','verify') AND publication_receipt IS NULL) OR (settlement_kind IS NOT NULL AND settlement_kind='cleanup_complete' AND completed_at IS NOT NULL AND checkpoint='cleanup')));
CREATE INDEX idx_lifecycle_transitions_checkpoint ON lifecycle_transitions(checkpoint,updated_at,id);
CREATE INDEX idx_lifecycle_transitions_target ON lifecycle_transitions(target_version_row_id,target_object_id);
